function glassSpec(){return [{base:.55,height:1.65},{base:.12,height:1.5},{base:.45,height:1.05}][s.glass||0]}
function glassRadius(t){t=Math.max(0,Math.min(1,t));return (s.glass||0)===0?.40+.43*t:(s.glass||0)===1?.63+.12*t:.42+.63*Math.sin(t*Math.PI/2)}
function glassMaterial(obj,opacity=.18){obj.traverse(o=>{if(o.material){o.material.transparent=true;o.material.opacity=opacity;o.material.depthWrite=false;o.material.roughness=.24;o.material.map=null;o.renderOrder=3}});return obj}
function parfaitBody(l){
 const {base,height}=glassSpec(),profile=[];for(let j=0;j<=40;j++)profile.push(new T.Vector2(glassRadius(j/40)+.045,base+j/40*height));
 glassMaterial(mesh(new T.LatheGeometry(profile,80),'#c5d7d3',world));
 for(let yy of [base,base+height]){let r=glassRadius((yy-base)/height)+.045,g=mesh(new T.TorusGeometry(r,.018,8,80),'#d1dfd7',world,[0,yy,0]);g.rotation.x=Math.PI/2;glassMaterial(g,.48)}
 if(base>.2){glassMaterial(cylinder(world,'#d0ddd7',.06,base-.05,base/2),.5);glassMaterial(cylinder(world,'#d0ddd7',.39,.045,.025),.45)}
 let floor=cylinder(world,'#e1e5da',glassRadius(0),.025,base);floor.userData.layer=0;surfaces.push(floor);
 const stack=s.stack||[];for(let i=0;i<stack.length;i++){
  let st=stack[i],bottom=base+i*height/8,top=bottom+height/8,r0=glassRadius(i/8)-.018,r1=glassRadius((i+1)/8)-.018,color=st.kind==='cream'?cp[st.i]:st.kind==='jam'?jamColors[st.i]:st.kind==='crumb'?pal[st.i]:cp[0];
  let m=mesh(new T.CylinderGeometry(r1,r0,height/8,80),color,world,[0,(bottom+top)/2,0]);m.userData.layer=0;surfaces.push(m);
  if(cutaway){let sh=new T.Shape();sh.moveTo(-r0,bottom);sh.lineTo(r0,bottom);sh.lineTo(r1,top);sh.lineTo(-r1,top);sh.closePath();noClip(mesh(new T.ShapeGeometry(sh),color,capGroup,[0,0,.002]))}
  if(st.kind==='fruit'){let g=new T.Group();world.add(g);for(let j=0;j<12;j++){let a=j*Math.PI/6,f=ornament('fruits',st.i);f.position.set(Math.cos(a)*((r0+r1)/2-.075),bottom+.01,Math.sin(a)*((r0+r1)/2-.075));f.rotation.y=-a;f.scale.set(.53,(height/8)/.35,.53);g.add(f)}if(cutaway)addFruitCaps(g)}
  if(st.kind==='crumb')for(let j=0;j<45;j++){let a=j*2.399,rad=(r0-.025)*Math.sqrt((j+.5)/45),yy=bottom+.025+(j%5)/5*(height/8-.025);sphere(world,pal[st.i],Math.cos(a)*rad,yy,Math.sin(a)*rad,.028,.022,.025)}
 }
 l._bottom=base;l._y=base+stack.length*height/8;l.r=glassRadius(stack.length/8)-.035;return base+height;
}
function addParfaitLayer(kind,i){if((s.stack||[]).length>=8)return;checkpoint();(s.stack??=[]).push({kind,i});sel=-1;hideGhost();update()}
