function sideRingModel(it){
 const result=new T.Group(),l=s.layers[it.layer],r=l.r,k=it.scale||1;
 const sample=ornament(it.key,it.i);if(it.key!=='borders')sample.rotation.x=Math.PI/2;sample.updateMatrixWorld(true);const box=new T.Box3().setFromObject(sample),dim=box.getSize(new T.Vector3());
 const h=isPie()?.27:.4,scale=Math.min(.85*k,Math.min(h*.72,Math.max(.06,2*Math.min(h+it.y,-it.y)*.95))/Math.max(.04,dim.y)),width=Math.max(.10,dim.x*scale),n=Math.max(6,Math.min(48,Math.round(Math.PI*2*r/(width*1.12))));
 for(let j=0;j<n;j++)sample.traverse(o=>{if(!o.isMesh)return;const geo=o.geometry.clone(),p=geo.attributes.position;for(let v=0;v<p.count;v++){let pt=new T.Vector3().fromBufferAttribute(p,v).applyMatrix4(o.matrixWorld),yy=(pt.y-(box.min.y+box.max.y)/2)*scale,depth=(pt.z-box.min.z)*scale+.009,vertical=l._y+it.y+yy-l._bottom;let rr=isCup()?r*(.76+.24*Math.max(0,Math.min(1,vertical/.4))):isPie()?r*(.83+.17*Math.max(0,Math.min(1,vertical/.31))):r;let a=j*Math.PI*2/n+pt.x*scale/r+(it.twist||0);p.setXYZ(v,Math.sin(a)*(rr+depth),yy,Math.cos(a)*(rr+depth))}geo.computeVertexNormals();result.add(new T.Mesh(geo,o.material.clone()))});disposeGroup(sample);return result;
}
function sideRingArrange(){if(isParfait()||isPetite()||!s.layers.length||s.items.length>=240)return;const src=sel>=0?s.items[sel]:{key:tab,i:chosen};if(!['piping','fruits','decor','borders'].includes(src.key))return;checkpoint();const layer=Math.min(sideLayer,s.layers.length-1);s.items.push({key:src.key,i:src.i,layer,x:0,z:0,y:isPie()?-.13:-.2,normal:[0,0,1],scale:1,twist:0,sideRing:true});sel=s.items.length-1;targetPitch=.25;cutaway=false;hideGhost();update()}
function litScene(){let sc=new T.Scene();sc.add(new T.HemisphereLight(0xfffaf2,0xd6c3b1,2.3));let sun=new T.DirectionalLight(0xfff4e3,2);sun.position.set(-4,8,5);sc.add(sun);return sc}
function initShowcase(){
 menuRenderer=new T.WebGLRenderer({canvas:$('menu-scene'),alpha:true,antialias:true,preserveDrawingBuffer:true});menuRenderer.setPixelRatio(Math.min(devicePixelRatio,2));menuRenderer.outputColorSpace=T.SRGBColorSpace;menuRenderer.setClearColor(0,0);
 // Palette previews use the same meshes as the placed objects.
 const previewScene=litScene(),cam=new T.PerspectiveCamera(34,1,.01,100);menuRenderer.setSize(160,160,false);let savedCut=cutaway;cutaway=false;
 for(let [key,count] of [['fruits',20],['decor',20],['piping',16],['borders',9]]){thumbs[key]=[];for(let i=0;i<count;i++){let g=ornament(key,i);previewScene.add(g);let b=new T.Box3().setFromObject(g),center=b.getCenter(new T.Vector3()),d=b.getSize(new T.Vector3()).length();cam.position.copy(center).add(new T.Vector3(.5,.8,1).normalize().multiplyScalar(d*2));cam.lookAt(center);menuRenderer.render(previewScene,cam);thumbs[key].push(menuRenderer.domElement.toDataURL());previewScene.remove(g);disposeGroup(g)}}
 const oldS=s,oldDessert=dessert,oldSel=sel;sel=-1;
 const demos=[{kind:'cake',state:{layers:[{r:1.1,flavor:0,fill:0,coat:1},{r:.85,flavor:0,fill:null,coat:1}],items:[{key:'borders',i:3,sideRing:true,layer:0,x:0,z:0,y:-.18,scale:1},{key:'decor',i:0,layer:1,x:0,z:0,y:0,scale:1.7}],plate:0}},{kind:'cupcake',state:{layers:[{r:.83,flavor:0,fill:null,coat:null}],wrapper:1,pattern:1,items:[{key:'swirl',i:1,layer:0,x:0,z:0,y:0,scale:1},{key:'fruits',i:2,layer:0,x:0,z:0,y:.75,scale:.8}],plate:0}},{kind:'pie',state:{layers:[{r:1.2,flavor:0}],custard:1,crust:0,edge:1,topping:0,items:Array.from({length:9},(_,j)=>({key:'fruits',i:j%2?3:0,layer:0,x:Math.sin(j*Math.PI*2/9)*.78,z:Math.cos(j*Math.PI*2/9)*.78,y:0,scale:.9})),plate:0}},{kind:'parfait',state:{layers:[{r:.8}],glass:0,stack:[{kind:'jam',i:0},{kind:'cream',i:0},{kind:'fruit',i:3},{kind:'cream',i:1},{kind:'crumb',i:0},{kind:'cream',i:0},{kind:'jam',i:0}],items:[{key:'scoops',i:1,layer:0,x:-.25,z:0,y:0,scale:1},{key:'scoops',i:3,layer:0,x:.25,z:0,y:0,scale:1},{key:'fruits',i:2,layer:0,x:0,z:0,y:.48,scale:.8}],plate:0}}];
 demos.push({kind:'pudding',state:{layers:[{r:.85,flavor:0}],sauce:0,items:[{key:'piping',i:0,layer:0,x:0,z:0,y:0,scale:1.3},{key:'fruits',i:2,layer:0,x:0,z:0,y:.33,scale:.8}],plate:0}},{kind:'pancake',state:{layers:[{r:1.1,flavor:0}],count:3,sauce:1,items:[{key:'fruits',i:0,layer:0,x:.25,z:0,y:0,scale:1.1},{key:'fruits',i:3,layer:0,x:-.35,z:0,y:0,scale:1}],plate:0}});
 for(let demo of demos){s=demo.state;dessert=demo.kind;build();const sc=litScene(),g=new T.Group();let all=[...world.children];all.slice(0,65).forEach(o=>{world.remove(o);let trash=new T.Group();trash.add(o);disposeGroup(trash)});for(let o of [...world.children])g.add(o);let b=new T.Box3().setFromObject(g),center=b.getCenter(new T.Vector3()),sz=b.getSize(new T.Vector3());for(let o of g.children)o.position.sub(center);sc.add(g);menuViews.push({scene:sc,group:g,camera:new T.PerspectiveCamera(35,1,.01,100),extent:Math.max(sz.x,sz.y,sz.z),kind:demo.kind})}
 s=oldS;dessert=oldDessert;sel=oldSel;cutaway=savedCut;build();
}
function renderShowcase(){if(!menuRenderer||$('desserts').hidden)return false;if(menuWidth!==innerWidth||menuHeight!==innerHeight){menuRenderer.setSize(innerWidth,innerHeight,false);menuWidth=innerWidth;menuHeight=innerHeight}menuRenderer.setScissorTest(false);menuRenderer.clear();menuRenderer.setScissorTest(true);const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches,time=performance.now()/1000;
 menuViews.forEach((v,i)=>{let el=document.querySelector('[data-dessert="'+v.kind+'"]'),r=el.getBoundingClientRect();if(!r.width||!r.height)return;menuRenderer.setViewport(r.left,innerHeight-r.bottom,r.width,r.height);menuRenderer.setScissor(r.left,innerHeight-r.bottom,r.width,r.height);v.camera.aspect=r.width/r.height;v.camera.position.set(0,v.extent*.65,v.extent*2.15);v.camera.lookAt(0,0,0);v.camera.updateProjectionMatrix();v.group.position.y=reduce?0:Math.sin(time*.85+i*1.6)*v.extent*.055;v.group.rotation.y=.35+(reduce?0:Math.sin(time*.3+i)*.18);v.group.rotation.z=reduce?0:Math.sin(time*.6+i)*.035;menuRenderer.render(v.scene,v.camera)});menuRenderer.setScissorTest(false);return true}
function checkpoint(){hist.push(JSON.stringify(s));if(hist.length>40)hist.shift()}
function persist(){try{localStorage.setItem(storageKey(),JSON.stringify(s))}catch{}}
function update(){persist();build();ui()}
function disposeGroup(group){while(group.children.length){const o=group.children[0];group.remove(o);o.traverse(c=>{c.geometry?.dispose();for(const m of Array.isArray(c.material)?c.material:c.material?[c.material]:[]){if(m.map&&m.map!==paintTexture)m.map.dispose();m.dispose()}})}}
function noClip(obj){obj.traverse(o=>{for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[])m.clippingPlanes=[]});return obj}
