canvas.onpointerdown=e=>{if(!ready)return;canvas.setPointerCapture(e.pointerId);autoSpin=false;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false,item:-1};hideGhost();if(cutaway||photo||mode==='rotate')return;let p=location(e);if(mode==='paint'&&[1,3].includes(s.stage)&&p){checkpoint();dab(p);lastStamp=p;pointer.paint=true;return}if(mode==='place'&&[2,4].includes(s.stage)){if(continuous&&s.stage===4&&tab==='piping'&&p){checkpoint();place(p,false);lastStamp=p;pointer.pipe=true;return}let hit=intersects(e,parts).find(h=>{let it=s.items[h.object.userData.item];return it&&it.key!=='swirl'&&(!it.filling||(s.stage===2&&it.layer===s.layers.length-1))});if(hit){sel=hit.object.userData.item;pointer.item=sel;checkpoint();build();ui()}}};
canvas.onpointermove=e=>{if(!ready)return;const p=(!cutaway&&!photo&&mode!=='rotate')?location(e):null;if(!pointer){preview(p);return}let dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;pointer.moved ||= Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>4;if(mode==='rotate'||cutaway||photo){targetYaw-=dx*.007;targetPitch=Math.max(.08,Math.min(1.54,targetPitch+dy*.006))}else if(pointer.paint&&p){if(pointDistance(p,lastStamp)>.045&&performance.now()-strokeClock>35){dab(p);lastStamp=p;strokeClock=performance.now()}}else if(pointer.pipe&&p){if(pointDistance(p,lastStamp)>.17){place(p,false);lastStamp=p}}else if(pointer.item>=0&&p&&!s.items[pointer.item].sideRing){Object.assign(s.items[pointer.item],p);landing=null;build()}else preview(p);pointer.x=e.clientX;pointer.y=e.clientY};
canvas.onpointerup=e=>{if(!pointer)return;if(!cutaway&&!photo&&mode==='place'&&pointer.item<0&&!pointer.pipe&&!pointer.moved&&[2,4].includes(s.stage)){let p=location(e);if(p){checkpoint();place(p)}}if(pointer?.pipe)build();persist();pointer=null;lastStamp=null;ui()};canvas.onpointercancel=()=>{pointer=null;lastStamp=null;persist();ui()};canvas.onpointerleave=()=>{if(!pointer)hideGhost()};canvas.addEventListener('wheel',e=>{e.preventDefault();autoSpin=false;dist=Math.max(5.5,Math.min(14,dist+e.deltaY*.006))},{passive:false});
function photoLayout(){const tray=$('tray').getBoundingClientRect(),available=Math.max(100,tray.top-30),side=Math.max(80,Math.min(innerWidth-24,available,760));return {side,left:(innerWidth-side)/2,top:Math.max(12,(available-side)/2)}}
function resize(){const overlay=$('photo-frame');if(photo){const r=photoLayout();renderer.setSize(r.side,r.side,false);Object.assign(canvas.style,{width:r.side+'px',height:r.side+'px',left:r.left+'px',top:r.top+'px',right:'auto',bottom:'auto'});Object.assign(overlay.style,{width:r.side+'px',height:r.side+'px',left:r.left+'px',top:r.top+'px'});overlay.hidden=false;overlay.width=1000;overlay.height=1000;drawFrame(overlay.getContext('2d'),frameStyle,1000);camera.aspect=1;camera.clearViewOffset();canvas.style.background=backgrounds[background]}else{renderer.setSize(innerWidth,innerHeight);Object.assign(canvas.style,{width:'100%',height:'100%',left:'0px',top:'0px',background:'transparent'});overlay.hidden=true;camera.aspect=innerWidth/innerHeight}camera.updateProjectionMatrix()}
addEventListener('resize',resize);resize();
function frame(){requestAnimationFrame(frame);if(renderShowcase())return;if(autoSpin&&!pointer)targetYaw+=.002;if(landing){landing.t+=.065;let g=parts[landing.index],it=s.items[landing.index];if(g&&it){positionItem(g,it);g.position.y+=.15*Math.pow(Math.max(0,1-landing.t),2)}if(landing.t>=1)landing=null}pitch+=(targetPitch-pitch)*.13;yaw+=(targetYaw-yaw)*.13;camera.position.set(viewCenter.x+Math.sin(yaw)*Math.cos(pitch)*dist,viewCenter.y+Math.sin(pitch)*dist,Math.cos(yaw)*Math.cos(pitch)*dist);camera.lookAt(viewCenter);if(photo)camera.clearViewOffset();else camera.setViewOffset(innerWidth,innerHeight,0,innerHeight*.09,innerWidth,innerHeight);renderer.render(scene,camera)}frame();
function download(){const oldSel=sel,oldAspect=camera.aspect,oldView=camera.view?{...camera.view}:null;sel=-1;landing=null;hideGhost();let out=document.createElement('canvas');out.width=out.height=1600;try{build();camera.clearViewOffset();camera.aspect=1;camera.updateProjectionMatrix();renderer.setSize(1600,1600,false);renderer.render(scene,camera);const g=out.getContext('2d');g.fillStyle=backgrounds[background];g.fillRect(0,0,1600,1600);g.drawImage(canvas,0,0,1600,1600);drawFrame(g,frameStyle,1600)}finally{sel=oldSel;camera.aspect=oldAspect;camera.view=oldView;resize();build()}
 out.toBlob(blob=>{if(!blob)return;let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=({pudding:'我的布丁',pancake:'我的鬆餅',parfait:'我的芭菲杯',pie:'我的派塔',cupcake:'我的杯子蛋糕',cake:'我的蛋糕'}[dessert])+(cutaway?'-剖面':'-外觀')+'-'+frameNames[frameStyle]+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png')}
function frameControls(){frameNames.forEach((name,i)=>{let b=document.createElement('button');b.setAttribute('aria-label',name+'相框');b.setAttribute('aria-pressed',String(frameStyle===i));b.className=frameStyle===i?'selected':'';let c=document.createElement('canvas');c.width=c.height=100;let g=c.getContext('2d');g.fillStyle=backgrounds[background];g.fillRect(0,0,100,100);drawFrame(g,i,100);g.fillStyle='#c9a8a5';g.beginPath();g.ellipse(50,57,19,7,0,0,Math.PI*2);g.fill();g.fillRect(31,43,38,14);g.fillStyle='#ead0c7';g.beginPath();g.ellipse(50,43,19,7,0,0,Math.PI*2);g.fill();b.appendChild(c);b.onclick=()=>{frameStyle=i;photo=true;autoSpin=false;ui()};$('palette').appendChild(b)})}
async function atlas(key,cols,rows){let im=await new Promise((ok,no)=>{let img=new Image();img.onload=()=>ok(img);img.onerror=no;img.src='assets/'+key+'.png'});thumbs[key]=[];for(let n=0;n<cols*rows;n++){let w=Math.floor(im.width/cols),h=Math.floor(im.height/rows),c=document.createElement('canvas');c.width=w;c.height=h;let g=c.getContext('2d');g.drawImage(im,n%cols*w,Math.floor(n/cols)*h,w,h,0,0,w,h);let d=g.getImageData(0,0,w,h),x0=w,y0=h,x1=0,y1=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(d.data[(y*w+x)*4+3]>120){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}let out=document.createElement('canvas');out.width=140;out.height=140;let k=Math.min(130/(x1-x0+1),130/(y1-y0+1)),ww=(x1-x0+1)*k,hh=(y1-y0+1)*k;out.getContext('2d').drawImage(c,x0,y0,x1-x0+1,y1-y0+1,(140-ww)/2,(140-hh)/2,ww,hh);thumbs[key].push(out.toDataURL())}}
Promise.all([['bases',3,2],['coats',3,2],['piping',4,4],['fruits',4,3],['decor',4,3],['candles',4,2],['borders',3,3]].map(a=>atlas(...a))).then(()=>{mode=(isPie()||isParfait())&&s.stage===1?'rotate':[1,3].includes(s.stage)?'paint':[2,4].includes(s.stage)?'place':'rotate';if(s.stage===2)tab='fruits';if(isParfait()){tab='scoops';glassChoice=s.glass||0;dist=8.6;if(s.stage===1)mode='rotate'}if(isPie()){tab='fruits';flavor=s.crust||0;size=s.size??1;if(s.stage===1)mode='rotate'}if(isCup()){tab='swirl';wrapper=s.wrapper||0;pattern=s.pattern||0;dist=7}if(isPetite()){tab='fruits';flavor=s.layers[0]?.flavor||0;size=s.size??1;mode=s.stage===4?'place':'rotate'}build();initShowcase();ready=true;$('loading').remove();ui();document.querySelectorAll('[data-dessert]').forEach(b=>b.onclick=()=>selectDessert(b.dataset.dessert));$('close-desserts').onclick=()=>{$('desserts').hidden=true};dessertMenu()}).catch(()=>{ $('loading').innerHTML='';button('loading','reset','素材載入失敗，重新載入',()=>window.location.reload())});

function petiteBody(l){
 const r=l.r,root=new T.Group();world.add(root);l._bottom=0;
 const sauceColors=['#a87853','#d0a16a','#ba8491','#8a6857'];
 if(dessert==='pudding'){
  const h=.85,profile=[[0,0],[r*.89,0],[r,.06],[r*.98,.13],[r*.75,h-.06],[r*.71,h],[0,h]].map(p=>new T.Vector2(...p));
  const geo=new T.LatheGeometry(profile,96),p=geo.attributes.position;for(let j=0;j<p.count;j++){let x=p.getX(j),z=p.getZ(j),f=1+.018*Math.cos(Math.atan2(z,x)*12);p.setX(j,x*f);p.setZ(j,z*f)}geo.computeVertexNormals();mesh(geo,[ '#eddbac','#e5bbc0','#ae8b73','#c1cba4','#dbc3c7','#c4bfb0'][l.flavor],root);
  l._y=h+.015;
  if(s.sauce!==null){const col=sauceColors[s.sauce||0];cylinder(root,col,r*.715,.025,h+.008);for(let j=0;j<12;j++){let a=j*Math.PI/6,len=.055+.05*(1+Math.sin(j*2.3));tube(root,col,[[Math.cos(a)*r*.7,h+.014,Math.sin(a)*r*.7],[Math.cos(a)*r*.758,h-.06,Math.sin(a)*r*.758],[Math.cos(a)*r*(.758+len*.28),h-.06-len,Math.sin(a)*r*(.758+len*.28)]],.017)}}
 }else{
  const n=s.count||3,h=.18,gap=.035;
  for(let j=0;j<n;j++){let y=j*(h+gap),profile=[[0,0],[r*.9,0],[r*.985,.035],[r,h*.5],[r*.985,h-.025],[r*.91,h],[0,h]].map(p=>new T.Vector2(p[0],p[1]+y));mesh(new T.LatheGeometry(profile,80),[ '#d7b17d','#d5a5a6','#a4866c','#b7be91','#bd8b8f','#b9afa0'][l.flavor],root);cylinder(root,[ '#e7c997','#e4b8b9','#b49a81','#c7d0a3','#d2a4a7','#cbc3b4'][l.flavor],r*.91,.012,y+h);if(j<n-1)cylinder(root,cp[s.cream??0],r*.94,gap,y+h+gap/2)}
  l._y=n*(h+gap)-gap+.015;
  if(s.sauce!==null){const col=sauceColors[s.sauce??1];cylinder(root,col,r*.70,.018,l._y+.003);for(let j=0;j<5;j++){let a=j*1.256,rr=r*.91;tube(root,col,[[Math.cos(a)*r*.59,l._y+.015,Math.sin(a)*r*.59],[Math.cos(a)*rr,l._y+.01,Math.sin(a)*rr],[Math.cos(a)*r*.994,l._y-.07,Math.sin(a)*r*.994]],.035)}}
 }
 root.traverse(o=>{if(o.isMesh){o.userData.layer=0;surfaces.push(o)}});if(cutaway)addFruitCaps(root);return l._y;
}
