 ['#a87853','#d0a16a','#ba8491','#8a6857'].forEach((c,i)=>pieChoice('options',['焦糖醬','楓糖醬','莓果醬','巧克力醬'][i],c,()=>{checkpoint();s.sauce=i;update()},(s.sauce??(dessert==='pudding'?0:1))===i&&s.sauce!==null,'fill'));
